"""Strict VIR v1 parser; JSON strings are decoded before reading separators.

Blank lines and CRLF line endings are accepted. The first nonempty line must
be the version/dimensions header. Records may appear in any order after it.
Unknown records, versions, duplicate IDs/captions/queries, malformed escapes,
nonfinite numbers and dangling references raise :class:`VIRParseError` with
the responsible one-based line number. No eval or executable DSL is used.
"""

from __future__ import annotations

from dataclasses import replace
import json
import math
import re

from virvision.scene import (
    Attribute,
    BBox,
    DetectedObject,
    DetectedText,
    Relation,
    SceneDescription,
    VisualScene,
)


class VIRParseError(ValueError):
    """Malformed or semantically invalid VIR document."""


_UNESCAPES = {"25": "%", "7C": "|", "3E": ">", "3A": ":", "0A": "\n", "0D": "\r"}
_NUMBER = re.compile(r"-?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?\Z")
_DECODER = json.JSONDecoder()


def _unescape(value: str) -> str:
    result = []
    index = 0
    while index < len(value):
        char = value[index]
        if char == "%":
            code = value[index + 1 : index + 3].upper()
            if code not in _UNESCAPES:
                raise ValueError(f"invalid percent escape at field offset {index}")
            result.append(_UNESCAPES[code])
            index += 3
        elif char in "|>:\n\r":
            raise ValueError(f"reserved character {char!r} must be percent-escaped")
        else:
            result.append(char)
            index += 1
    return "".join(result)


def _number(value: str) -> float:
    if not _NUMBER.fullmatch(value):
        raise ValueError(f"invalid numeric value {value!r}")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError("numbers must be finite")
    return result


def _bbox(value: str) -> BBox:
    parts = value.split(",")
    if len(parts) != 4:
        raise ValueError("bbox must contain four comma-separated coordinates")
    return BBox(*(_number(part) for part in parts))


def _quoted(value: str) -> tuple[str, str]:
    """Read exactly one JSON string, returning its unconsumed suffix."""
    if not value.startswith('"'):
        raise ValueError("expected a JSON quoted string")
    try:
        decoded, end = _DECODER.raw_decode(value)
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid JSON string: {exc.msg}") from exc
    return decoded, value[end:]


def _fields(value: str, count: int) -> list[str]:
    parts = value.split("|")
    if len(parts) != count:
        raise ValueError(f"expected {count} pipe-separated fields, got {len(parts)}")
    return parts


def _description(value: str) -> SceneDescription:
    decoded, suffix = _quoted(value)
    if not suffix.startswith("|"):
        raise ValueError("description requires |confidence after its JSON string")
    return SceneDescription(decoded, _number(suffix[1:]))


def parse_vir(text: str) -> VisualScene:
    """Parse VIR v1 into immutable scene data, preserving precision and Unicode."""
    if not isinstance(text, str):
        raise VIRParseError("VIR input must be a string")
    lines = [
        (index, line.removesuffix("\r"))
        for index, line in enumerate(text.split("\n"), 1)
        if line.strip()
    ]
    if not lines:
        raise VIRParseError("line 1: missing VIR header")
    header_line, header = lines[0]
    match = re.fullmatch(r"V1;([1-9][0-9]*)x([1-9][0-9]*)", header)
    if match is None:
        raise VIRParseError(
            f"line {header_line}: expected V1;WIDTHxHEIGHT header (only version 1 is supported)"
        )
    try:
        width, height = int(match[1]), int(match[2])
    except ValueError as exc:
        raise VIRParseError(f"line {header_line}: invalid image dimensions") from exc
    objects: list[DetectedObject] = []
    texts: list[DetectedText] = []
    relations: list[Relation] = []
    relation_lines: list[int] = []
    attributes: list[tuple[int, str, Attribute]] = []
    known_ids: set[str] = set()
    caption = None
    tags: list[SceneDescription] = []
    query = None
    has_query = False
    query_line = header_line
    for line_number, line in lines[1:]:
        try:
            record, separator, body = line.partition(":")
            if not separator:
                raise ValueError("record requires a colon separator")
            if re.fullmatch(r"O[1-9][0-9]*", record):
                if record in known_ids:
                    raise ValueError(f"duplicate ID {record}")
                label, bbox, confidence = _fields(body, 3)
                objects.append(
                    DetectedObject(record, _unescape(label), _bbox(bbox), _number(confidence))
                )
                known_ids.add(record)
            elif re.fullmatch(r"T[1-9][0-9]*", record):
                if record in known_ids:
                    raise ValueError(f"duplicate ID {record}")
                decoded, suffix = _quoted(body)
                if not suffix.startswith("|"):
                    raise ValueError("text requires |bbox|confidence after its JSON string")
                parts = suffix[1:].split("|")
                if len(parts) not in (2, 3):
                    raise ValueError("text requires bbox, confidence and optional language")
                language = _unescape(parts[2]) if len(parts) == 3 else None
                texts.append(
                    DetectedText(record, decoded, _bbox(parts[0]), _number(parts[1]), language)
                )
                known_ids.add(record)
            elif record == "A":
                parts = body.split("|", 2)
                if len(parts) != 3:
                    raise ValueError(
                        "attribute requires object ID, name, JSON value and confidence"
                    )
                owner, name, remaining = parts
                if not re.fullmatch(r"O[1-9][0-9]*", owner):
                    raise ValueError("attribute owner must be an object ID")
                value, suffix = _quoted(remaining)
                if not suffix.startswith("|"):
                    raise ValueError("attribute requires |confidence after its JSON value")
                attributes.append(
                    (line_number, owner, Attribute(_unescape(name), value, _number(suffix[1:])))
                )
            elif record == "R":
                edge, confidence = _fields(body, 2)
                endpoints = edge.split(">")
                if len(endpoints) != 3:
                    raise ValueError("relation requires source>predicate>target")
                source, predicate, target = endpoints
                relations.append(
                    Relation(source, _unescape(predicate), target, _number(confidence))
                )
                relation_lines.append(line_number)
            elif record == "C":
                if caption is not None:
                    raise ValueError("duplicate caption record")
                caption = _description(body)
            elif record == "S":
                tags.append(_description(body))
            elif record == "Q":
                if has_query:
                    raise ValueError("duplicate query record")
                query, suffix = _quoted(body)
                if suffix:
                    raise ValueError("unexpected content after query JSON string")
                has_query = True
                query_line = line_number
            else:
                raise ValueError(f"unknown or invalid record {record!r}")
        except (ValueError, TypeError, OverflowError) as exc:
            raise VIRParseError(f"line {line_number}: {exc}") from exc
    by_object: dict[str, list[Attribute]] = {obj.id: [] for obj in objects}
    for line_number, owner, attribute in attributes:
        if owner not in by_object:
            raise VIRParseError(f"line {line_number}: attribute references missing object {owner}")
        by_object[owner].append(attribute)
    for line_number, relation in zip(relation_lines, relations):
        missing = {relation.source, relation.target} - known_ids
        if missing:
            raise VIRParseError(
                f"line {line_number}: relation references missing IDs: {', '.join(sorted(missing))}"
            )
    objects = [replace(obj, attributes=tuple(by_object[obj.id])) for obj in objects]
    try:
        return VisualScene(
            width,
            height,
            tuple(objects),
            tuple(texts),
            tuple(relations),
            caption,
            tuple(tags),
            query,
        )
    except (ValueError, TypeError, OverflowError) as exc:
        # The query is the only value not validated by an observation model
        # above; associate Unicode/type validation failures with its own row.
        raise VIRParseError(f"line {query_line}: {exc}") from exc
